import unicodedata

def quitar_tildes(texto):
    descompuesto = unicodedata.normalize("NFD", texto)
    letras = [c for c in descompuesto if unicodedata.category(c) != "Mn"]
    return unicodedata.normalize("NFC", "".join(letras))

