import unicodedata

def es_palindromo(frase):
    descompuesta = unicodedata.normalize("NFD", frase.casefold())
    limpia = []
    for c in descompuesta:
        if c.isalnum():
            limpia.append(c)
    texto = "".join(limpia)
    return texto == texto[::-1]

