exercises.solution:
def cesar(texto, desplazamiento):
    resultado = []
    for c in texto:
        if "a" <= c <= "z":
            base = ord("a")
        elif "A" <= c <= "Z":
            base = ord("A")
        else:
            resultado.append(c)
            continue
        posicion = (ord(c) - base + desplazamiento) % 26
        resultado.append(chr(base + posicion))
    return "".join(resultado)

