def recortar_utf8(texto, max_bytes):
    usados = 0
    fin = 0
    for caracter in texto:
        tam = len(caracter.encode("utf-8"))
        if usados + tam > max_bytes:
            break
        usados += tam
        fin += 1
    return texto[:fin]

