import re
import unicodedata

def slugify(texto):
    descompuesto = unicodedata.normalize("NFKD", texto)
    sin_marcas = []
    for c in descompuesto:
        if not unicodedata.combining(c):
            sin_marcas.append(c)
    texto = "".join(sin_marcas).casefold()
    texto = re.sub(r"[^a-z0-9]+", "-", texto)
    return texto.strip("-")

