exercises.solution:
def texto_celda(celda):
    if isinstance(celda, float):
        return f"{celda:,.2f}"
    if isinstance(celda, int):
        return f"{celda:,}"
    return celda

def formatear_tabla(cabeceras, filas):
    textos = []
    for fila in filas:
        textos.append([texto_celda(celda) for celda in fila])

    anchos = []
    for i, cabecera in enumerate(cabeceras):
        ancho = len(cabecera)
        for fila in textos:
            ancho = max(ancho, len(fila[i]))
        anchos.append(ancho)

    lineas = [" | ".join([f"{c:^{a}}" for c, a in zip(cabeceras, anchos)])]
    lineas.append("-+-".join(["-" * a for a in anchos]))
    for fila, fila_texto in zip(filas, textos):
        celdas = []
        for original, texto, ancho in zip(fila, fila_texto, anchos):
            if isinstance(original, str):
                celdas.append(f"{texto:<{ancho}}")
            else:
                celdas.append(f"{texto:>{ancho}}")
        lineas.append(" | ".join(celdas))
    return "\n".join(lineas)

