import re
import unicodedata

PALABRA = re.compile(r"[^\W\d_]+")

def normalizar(texto):
    return unicodedata.normalize("NFC", texto.casefold())

def palabras(texto):
    return PALABRA.findall(normalizar(texto))

def frecuencias(texto):
    conteo = {}
    for palabra in palabras(texto):
        conteo[palabra] = conteo.get(palabra, 0) + 1
    return conteo

def clave_ranking(par):
    palabra, veces = par
    return (-veces, palabra)

def top_palabras(texto, n):
    ordenadas = sorted(frecuencias(texto).items(), key=clave_ranking)
    return ordenadas[:n]

def informe(texto, n):
    lista = palabras(texto)
    total = len(lista)
    lineas = [f"Palabras: {total} | Distintas: {len(set(lista))}"]
    if total == 0:
        return lineas[0]
    lineas.append(f"{'Nº':>3}  {'Palabra':<12}  {'Veces':>5}  {'%':>6}")
    for posicion, (palabra, veces) in enumerate(top_palabras(texto, n), start=1):
        lineas.append(f"{posicion:>3}  {palabra:<12}  {veces:>5}  {veces / total:>6.1%}")
    return "\n".join(lineas)

