import re
from html import escape

MARCADOR = re.compile(r"""
    \{\{ \s*
    (?P<nombre>[A-Za-z_][A-Za-z0-9_]*)       # nombre de la variable
    \s*
    (?P<filtros>(?: \| \s* [a-z]+ \s* )*)    # cero o más "| filtro"
    \}\}
""", re.VERBOSE)

def formato_moneda(numero):
    texto = f"{abs(numero):,.2f}"                          # 1,234.50
    texto = texto.translate(str.maketrans(",.", ".,"))    # 1.234,50
    if numero < 0:
        return "-$" + texto
    return "$" + texto

def aplicar_filtro(valor, filtro):
    match filtro:
        case "mayus":
            return str(valor).upper()
        case "minus":
            return str(valor).lower()
        case "titulo":
            return str(valor).title()
        case "recortar":
            return str(valor).strip()
        case "moneda":
            return formato_moneda(valor)
        case "html":
            return escape(str(valor))
        case _:
            return None                                          # filtro desconocido

def sustituir(m, datos):
    nombre = m.group("nombre")
    if nombre not in datos:
        return m.group(0)
    valor = datos[nombre]
    for filtro in m.group("filtros").split("|"):
        filtro = filtro.strip()
        if filtro == "":
            continue
        valor = aplicar_filtro(valor, filtro)
        if valor is None:
            return m.group(0)
    return str(valor)

def renderizar(plantilla, datos):
    trozos = []
    posicion = 0
    for m in MARCADOR.finditer(plantilla):
        trozos.append(plantilla[posicion:m.start()])   # texto entre marcadores
        trozos.append(sustituir(m, datos))
        posicion = m.end()
    trozos.append(plantilla[posicion:])                # texto tras el último
    return "".join(trozos)

